#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

int find_center(int n, const vector<vector<int>>& adj) {
    auto bfs = [&](int start) {
        vector<int> dist(n + 1, -1);
        queue<int> q;
        dist[start] = 0;
        q.push(start);
        int farthest = start;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            if (dist[u] > dist[farthest]) {
                farthest = u;
            }
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return farthest;
    };

    int u = bfs(1);

    // BFS a partir de u salvando o parentesco para reconstruir o caminho
    vector<int> dist(n + 1, -1);
    vector<int> parent(n + 1, 0);
    queue<int> q;
    dist[u] = 0;
    q.push(u);
    int v = u;
    while (!q.empty()) {
        int curr = q.front();
        q.pop();
        if (dist[curr] > dist[v]) {
            v = curr;
        }
        for (int nxt : adj[curr]) {
            if (dist[nxt] == -1) {
                dist[nxt] = dist[curr] + 1;
                parent[nxt] = curr;
                q.push(nxt);
            }
        }
    }

    vector<int> path;
    int curr = v;
    while (curr != 0) {
        path.push_back(curr);
        curr = parent[curr];
    }

    return path[path.size() / 2];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> adj1(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj1[u].push_back(v);
        adj1[v].push_back(u);
    }

    vector<vector<int>> adj2(m + 1);
    for (int i = 0; i < m - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj2[u].push_back(v);
        adj2[v].push_back(u);
    }

    int c1 = find_center(n, adj1);
    int c2 = find_center(m, adj2);

    cout << c1 << " " << c2 << "\n";

    return 0;
}
